  F --> G{Need global order without a lock manager?}
  G -->|Yes| H[Timestamp ordering]

class Row:
    def __init__(self, value):
        self.versions = [(0, value)]  # (commit_ts, value) sorted by ts
        self.lock = False

class Store:
    def __init__(self):
        self.rows = {}
        self.clock = 0

    def snapshot_read(self, key, read_ts):
        # MVCC read: newest version with commit_ts <= read_ts.
        # Readers never take a lock; they just ignore newer versions.
        versions = self.rows[key].versions
        visible = [v for ts, v in versions if ts <= read_ts]
        return max(visible, default=None) if visible else None

    def occ_commit(self, read_set, write_set, read_ts):
        # Optimistic validation: abort if anyone committed a
        # write to our read set after we snapshotted.
        # Trade-off: no blocking, but wasted work on abort.
        for key, read_version_ts in read_set.items():
            latest_ts = self.rows[key].versions[-1][0]
            if latest_ts > read_ts:
                return False  # abort, caller retries with backoff
        self.clock += 1
        for key, val in write_set.items():
            self.rows[key].versions.append((self.clock, val))
        return True
